/**
 * Helpers for authentication tests. Every key and code here is generated by
 * the test itself; nothing is printed.
 */
import { eq } from 'drizzle-orm';
import type { DB } from '@/db';
import { sessions, users } from '@/db/schema';
import { confirmMfaSetup, startMfaSetup } from '@/server/auth/mfa';
import { totpCode } from '@/server/auth/totp';
import { createSession } from '@/server/services/team';

/** The password tests/helpers/world.ts gives every account. */
export const PASSWORD = 'correct horse battery';

export const minutes = (n: number) => n * 60_000;
export const at = (base: Date, ms: number) => new Date(base.getTime() + ms);

/**
 * Turn on two-step verification for an account, as the person would: start
 * setup, read the key, confirm with a code. The code is accepted `ago`
 * milliseconds in the past so that a code for "now" is not a replay.
 */
export async function enableMfa(db: DB, userId: string, opts: { ago?: number; keepToken?: string | null } = {}) {
  const confirmedAt = new Date(Date.now() - (opts.ago ?? minutes(10)));
  const { secret } = await startMfaSetup(db, userId);
  const { recoveryCodes } = await confirmMfaSetup(db, userId, totpCode(secret, confirmedAt), opts.keepToken ?? null, { now: confirmedAt });
  return { secret, recoveryCodes, confirmedAt };
}

/** A session that has passed two-step verification, as if the person had just signed in with a code. */
export async function verifiedSession(db: DB, userId: string, orgId?: string | null) {
  return createSession(db, userId, orgId ?? null, { mfaVerified: true });
}

export async function sessionRows(db: DB, userId: string) {
  return db.select().from(sessions).where(eq(sessions.userId, userId));
}

export async function userRow(db: DB, userId: string) {
  const [row] = await db.select().from(users).where(eq(users.id, userId));
  return row!;
}
